import math

def gcd(a, b):
    return math.gcd(a, b)

def lcm(a, b):
    if a == 0 or b == 0:
        return 0
    return abs(a * b) // gcd(a, b)

def generator(rng):
    while True:
        n = rng.choice([3, 4])
        p = rng.choice([2, 3])
        target_idx = rng.randint(1, n)

        # Constructive approach to guarantee integer v_i and a nice integer answer A.
        # Let a_i = log_w(x_i). The problem is a_i + p*a_{i+1} = 1/v_i.
        # Let the target be x_n, so the answer is 1/a_n = A. Thus a_n = 1/A.
        # We set a_i = r_i * a_n for i=1..n-1, where r_i are small random integers.
        # This gives a_n = 1/A, and a_i = r_i/A.

        r = [0] * (n - 1)
        for i in range(n - 1):
            r[i] = rng.randint(1, 4)

        # From a_i + p*a_{i+1} = 1/v_i, we derive denominators for A.
        # For i=1..n-2: a_i + p*a_{i+1} = (r_i + p*r_{i+1})/A = 1/v_i => v_i = A / (r_i + p*r_{i+1})
        # For i=n-1: a_{n-1} + p*a_n = (r_{n-1} + p)/A = 1/v_{n-1} => v_{n-1} = A / (r_{n-1} + p)
        # For i=n: a_n + p*a_1 = (1 + p*r_0)/A = 1/v_n => v_n = A / (1 + p*r_0)
        denominators = []
        if n > 2:
            for i in range(n - 2):
                denominators.append(r[i] + p * r[i+1])
        denominators.append(r[-1] + p)
        denominators.append(1 + p * r[0])

        if any(d <= 0 for d in denominators):
            continue

        L = 1
        for d in denominators:
            L = lcm(L, d)

        A = L * rng.randint(1, 4)

        # v_i are the reciprocals of k_i = a_i + p*a_{i+1}
        # The list `denominators` corresponds to k_1*A, k_2*A, ..., k_{n-1}*A, k_n*A
        v = [A // d for d in denominators]

        # The problem was constructed for target x_n. We rotate to match the random target_idx.
        shift = n - target_idx
        v_final = v[shift:] + v[:shift]

        # Ensure the problem is not trivial
        if len(set(v_final)) > 1:
            return {
                "n": n,
                "p": p,
                "v_values": f"({', '.join(map(str, v_final))})",
                "v_list": v_final,
                "target_idx": target_idx,
                "answer": A
            }

        from fractions import Fraction

def verifier(assign):
    n = assign['n']
    p = assign['p']
    v = assign['v_list']
    target_idx = assign['target_idx']
    answer = assign['answer']

    # Difficulty check: ensure not all v_i are the same, which allows a shortcut.
    if len(set(v)) <= 1:
        # This would allow the guess x_1=x_2=...=x_n, simplifying the problem dramatically.
        return False, None

    # Convert v_i to k_i = 1/v_i
    try:
        k = [Fraction(1, val) for val in v]
    except ZeroDivisionError:
        return False, None # v_i must be non-zero.

    # Let a_i = log_w(x_i). The system is a_i + p*a_{i+1} = k_i (with cyclic indices).
    # This is a linear system M*a = k. The matrix M is a circulant matrix.
    # The determinant is 1 - (-p)^n.
    det = Fraction(1 - (-p)**n)
    if det == 0:
        return False, None # System is singular

    # Calculate a_j for all j to check for positivity.
    a = [Fraction(0)] * n
    for j in range(n):
        # The general solution for a_j is (1/det) * sum_{i=0}^{n-1} (-p)^i * k_{j+i}
        # Indices are 0-based, modulo n.
        numerator = sum((Fraction(-p)**i) * k[(j + i) % n] for i in range(n))
        a[j] = numerator / det

    # All x_j > 1 and w > 1 implies log_w(x_j) > 0, so all a_j must be positive.
    if any(val <= 0 for val in a):
        return False, None

    # The value to be found is log_{x_{target_idx}} w = 1/a_{target_idx-1}
    target_a = a[target_idx - 1]

    if target_a == 0:
        return False, None # Answer would be infinite

    computed_answer = 1 / target_a

    # The answer must be an integer.
    if computed_answer.denominator != 1:
        return False, None

    if computed_answer.numerator != answer:
        return False, None

    return True, answer


        def generate_valid_instance(seed: int, timeout_seconds: float = 10.0):
